using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;

namespace Praxbit.Catalog.Controllers;

[ApiController]
[Route("api/[controller]")]
public class ProductsController : ControllerBase
{
    private readonly IProductService _service;

    public ProductsController(IProductService service) => _service = service;

    [HttpPost]
    public ActionResult<Product> Create(CreateProductRequest request)
    {
        var product = _service.Create(request.Name, request.Stock);
        return Created($"/api/products/{product.Id}", product);
    }
}

public record CreateProductRequest(
    [property: Required, StringLength(120)] string Name,
    [property: Range(0, 100000)] int Stock);
